// jt-glogarch project pages: language menu, screenshots, carousel, diagrams, copy buttons.
// English is the HTML itself; pages-i18n.js (generated by scripts/pages/build.py) holds zh-TW and ja.
(function () {
  'use strict'
  const T = window.PAGES_T || {}
  const LANGS = ['en', 'zh-TW', 'ja']
  const SHOT_SFX = { en: 'en', 'zh-TW': 'zhtw', ja: 'ja' }
  const GH = 'https://github.com/jasoncheng7115/jt-glogarch/blob/main/'
  const EN = new Map()      // the English text of every translated element, read once from the page
  let lang = 'en'

  for (const el of document.querySelectorAll('[data-t]')) {
    EN.set(el, el instanceof SVGElement ? el.textContent : el.innerHTML)
  }
  function tr(key) {
    if (lang === 'en' || !T[lang]) return null
    return T[lang][key] || null
  }
  function text(key) {               // a plain string for aria-labels, captions and button feedback
    const d = T[lang] || T.en || {}
    return ((d[key] || (T.en || {})[key]) || '').replace(/<[^>]+>/g, '')
  }

  function pick() {
    const q = new URLSearchParams(location.search).get('lang')
    if (LANGS.includes(q)) return q
    try { const s = localStorage.getItem('jt-pages-lang'); if (LANGS.includes(s)) return s } catch (e) { /* storage blocked */ }
    const n = (navigator.language || 'en').toLowerCase()
    return n.startsWith('zh') ? 'zh-TW' : n.startsWith('ja') ? 'ja' : 'en'
  }

  // an SVG label longer than its room is squeezed into it (data-w)
  function fit(root) {
    for (const el of root.querySelectorAll('svg text[data-w]')) {
      el.removeAttribute('textLength'); el.removeAttribute('lengthAdjust')
      let w = 0
      try { w = el.getComputedTextLength() } catch (e) { continue }
      if (w > +el.dataset.w) { el.setAttribute('textLength', el.dataset.w); el.setAttribute('lengthAdjust', 'spacingAndGlyphs') }
    }
  }

  function apply(l) {
    lang = l
    document.documentElement.lang = l
    for (const [el, en] of EN) {
      const v = tr(el.dataset.t)
      if (el instanceof SVGElement) el.textContent = v || en
      else el.innerHTML = v || en
    }
    for (const el of document.querySelectorAll('[data-ta]')) { const v = text(el.dataset.ta); el.setAttribute('aria-label', v); el.title = v }
    for (const b of document.querySelectorAll('#lang-menu button')) b.setAttribute('aria-checked', b.dataset.lang === l ? 'true' : 'false')
    document.getElementById('lang-cur').textContent = { en: 'EN', 'zh-TW': '繁中', ja: '日本語' }[l]
    // screenshots in the page's language
    const sfx = SHOT_SFX[l]
    for (const a of document.querySelectorAll('a[data-shot]')) {
      const base = 'screenshots/' + a.dataset.shot + '_' + sfx + '.png'
      a.href = base
      const img = a.querySelector('img'); if (img) img.src = base
    }
    for (const a of document.querySelectorAll('a[data-report]')) {
      const s = l === 'en' ? 'en' : 'zhtw'          // the sample report exists in English and Chinese
      a.href = 'reports/wazuh_' + a.dataset.report + '_' + s + '.png'
      const img = a.querySelector('img'); if (img) img.src = a.href
    }
    // links that have a translated document
    const cl = { 'zh-TW': '-zh_TW', ja: '-ja' }[l] || ''
    for (const a of document.querySelectorAll('.cl-link')) a.href = GH + 'CHANGELOG' + (l === 'zh-TW' ? '-zh_TW' : '') + '.md'
    for (const a of document.querySelectorAll('.readme-link')) a.href = GH + (l === 'en' ? 'README.md' : 'README' + cl + '.md')
    for (const a of document.querySelectorAll('.cfg-link')) a.href = GH + 'CONFIG' + (l === 'zh-TW' ? '-zh_TW' : '') + '.md'
    for (const a of document.querySelectorAll('.test-link')) a.href = GH + 'TESTING' + (l === 'zh-TW' ? '-zh_TW' : '') + '.md'
    for (const id of ['home-brand', 'home-btn', 'home-top']) { const a = document.getElementById(id); if (a) a.href = 'index.html?lang=' + l }
    for (const id of ['how-link', 'how-btn']) { const a = document.getElementById(id); if (a) a.href = 'how.html?lang=' + l }
    carCaption()
    fit(document)
    try { localStorage.setItem('jt-pages-lang', l) } catch (e) { /* storage blocked */ }
    const u = new URL(location.href); u.searchParams.set('lang', l); history.replaceState(null, '', u)
  }

  // ---- language menu ---------------------------------------------------------------------
  const langBtn = document.getElementById('lang-btn'), langMenu = document.getElementById('lang-menu')
  function langOpen(open, focus) {
    langMenu.hidden = !open
    langBtn.setAttribute('aria-expanded', open ? 'true' : 'false')
    if (open && focus) (langMenu.querySelector('[aria-checked="true"]') || langMenu.querySelector('button')).focus()
    if (!open && focus) langBtn.focus()
  }
  langBtn.addEventListener('click', () => langOpen(langMenu.hidden, true))
  for (const b of langMenu.querySelectorAll('button')) b.addEventListener('click', () => { apply(b.dataset.lang); langOpen(false, true) })
  langMenu.addEventListener('keydown', (e) => {
    const items = [...langMenu.querySelectorAll('button')], i = items.indexOf(document.activeElement)
    if (e.key === 'Escape') { e.preventDefault(); langOpen(false, true) }
    else if (e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1) % items.length].focus() }
    else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus() }
  })
  document.addEventListener('click', (e) => { if (!langMenu.hidden && !e.target.closest('.lang')) langOpen(false, false) })

  // ---- carousel (home) -------------------------------------------------------------------
  const car = document.getElementById('car')
  let carI = 0, carTimer = null
  function carCaption() {
    if (!car) return
    const s = car.querySelectorAll('.car-slide')[carI]
    document.getElementById('car-cap').textContent = text(s.dataset.cap)
  }
  function carGo(i) {
    const slides = car.querySelectorAll('.car-slide'), dots = car.querySelectorAll('.car-dots button')
    carI = (i + slides.length) % slides.length
    slides.forEach((s, n) => { s.classList.toggle('on', n === carI); s.setAttribute('aria-hidden', n === carI ? 'false' : 'true'); s.tabIndex = n === carI ? 0 : -1 })
    dots.forEach((d, n) => d.setAttribute('aria-current', n === carI ? 'true' : 'false'))
    carCaption()
  }
  function carPlay() {
    clearInterval(carTimer)
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    carTimer = setInterval(() => carGo(carI + 1), 6000)
  }
  if (car) {
    document.getElementById('car-prev').addEventListener('click', () => { carGo(carI - 1); carPlay() })
    document.getElementById('car-next').addEventListener('click', () => { carGo(carI + 1); carPlay() })
    for (const d of car.querySelectorAll('.car-dots button')) d.addEventListener('click', () => { carGo(+d.dataset.i); carPlay() })
    car.addEventListener('mouseenter', () => clearInterval(carTimer))
    car.addEventListener('mouseleave', carPlay)
    car.addEventListener('focusin', () => clearInterval(carTimer))
    car.addEventListener('keydown', (e) => { if (e.key === 'ArrowLeft') carGo(carI - 1); else if (e.key === 'ArrowRight') carGo(carI + 1) })
    carPlay()
  }

  // ---- screenshot lightbox ---------------------------------------------------------------
  const lb = document.getElementById('lb')
  let reportPages = null, reportI = 0
  function lbShow(src, title) {
    document.getElementById('lb-img').src = src
    document.getElementById('lb-open').href = src
    document.getElementById('lb-title').textContent = title || ''
  }
  document.addEventListener('click', (e) => {
    const a = e.target.closest('a.shotlink')
    if (!a || !lb || !lb.showModal || e.ctrlKey || e.metaKey || e.shiftKey) return
    e.preventDefault()
    const fig = a.closest('figure')
    const cap = fig && fig.querySelector('figcaption') ? fig.querySelector('figcaption').textContent : (a.dataset.cap ? text(a.dataset.cap) : '')
    reportPages = null
    if (a.dataset.report) {             // the sample report: page through its pages
      const s = lang === 'en' ? 'en' : 'zhtw'
      reportPages = [1, 2, 3, 4, 5].map((n) => 'reports/pages/wazuh_' + a.dataset.report + '_' + s + '_' + n + '.jpg')
      reportI = 0
      lbShow(reportPages[0], cap + ' (1/5)')
    } else lbShow(a.href, cap)
    lb.showModal()
    document.body.classList.add('zm-on')
  })
  if (lb) {
    document.getElementById('lb-x').addEventListener('click', () => lb.close())
    lb.addEventListener('click', (e) => {
      if (e.target === lb) { lb.close(); return }
      if (reportPages && e.target.id === 'lb-img') {
        reportI = (reportI + 1) % reportPages.length
        const title = document.getElementById('lb-title').textContent.replace(/ \(\d+\/5\)$/, '')
        lbShow(reportPages[reportI], title + ' (' + (reportI + 1) + '/5)')
      }
    })
    lb.addEventListener('close', () => document.body.classList.remove('zm-on'))
  }

  // ---- diagram zoom ----------------------------------------------------------------------
  const zoom = document.getElementById('zoom'), zmBody = document.getElementById('zm-body')
  let zmScale = 1, zmPan = null
  function zmFitWidth() {
    const svg = zmBody.querySelector('svg')
    if (!svg) return 1100
    const vb = svg.viewBox && svg.viewBox.baseVal && svg.viewBox.baseVal.width ? svg.viewBox.baseVal : { width: 1100, height: 620 }
    return Math.max(320, Math.min(zmBody.clientWidth - 30, (zmBody.clientHeight - 30) * vb.width / vb.height))
  }
  function zmSize(anchor) {
    const svg = zmBody.querySelector('svg')
    if (!svg) return
    const r0 = svg.getBoundingClientRect()
    const fx = anchor ? (zmBody.scrollLeft + anchor[0]) / (r0.width || 1) : 0, fy = anchor ? (zmBody.scrollTop + anchor[1]) / (r0.height || 1) : 0
    svg.style.width = Math.round(zmFitWidth() * zmScale) + 'px'
    document.getElementById('zm-pct').textContent = Math.round(zmScale * 100) + '%'
    if (anchor) { const r = svg.getBoundingClientRect(); zmBody.scrollLeft = fx * r.width - anchor[0]; zmBody.scrollTop = fy * r.height - anchor[1] }
  }
  function zmBy(f, anchor) { zmScale = Math.max(0.5, Math.min(4, zmScale * f)); zmSize(anchor) }
  if (zoom && zoom.showModal) {
    for (const b of document.querySelectorAll('button.zoom')) b.addEventListener('click', () => {
      const svg = document.getElementById(b.dataset.fig).querySelector('svg').cloneNode(true)
      zmBody.replaceChildren(svg)
      document.getElementById('zm-title').textContent = svg.querySelector('title').textContent
      zoom.showModal()
      fit(zmBody)
      zmScale = 1; zmSize()
      zmBody.scrollTop = 0; zmBody.scrollLeft = 0
      document.body.classList.add('zm-on')
    })
    document.getElementById('zm-in').addEventListener('click', () => zmBy(1.25))
    document.getElementById('zm-out').addEventListener('click', () => zmBy(1 / 1.25))
    document.getElementById('zm-fit').addEventListener('click', () => { zmScale = 1; zmSize() })
    window.addEventListener('resize', () => { if (zoom.open) zmSize() })
    zmBody.addEventListener('wheel', (e) => {
      if (!e.ctrlKey && !e.metaKey) return
      e.preventDefault()
      const r = zmBody.getBoundingClientRect()
      zmBy(Math.exp(-e.deltaY * 0.0025), [e.clientX - r.left, e.clientY - r.top])
    }, { passive: false })
    zmBody.addEventListener('pointerdown', (e) => { if (e.button === 0) zmPan = { x: e.clientX, y: e.clientY, l: zmBody.scrollLeft, t: zmBody.scrollTop, moved: false } })
    zmBody.addEventListener('pointermove', (e) => {
      if (!zmPan) return
      const dx = e.clientX - zmPan.x, dy = e.clientY - zmPan.y
      if (!zmPan.moved && Math.hypot(dx, dy) < 4) return
      zmPan.moved = true; zmBody.classList.add('panning')
      zmBody.scrollLeft = zmPan.l - dx; zmBody.scrollTop = zmPan.t - dy
    })
    for (const ev of ['pointerup', 'pointercancel', 'pointerleave']) zmBody.addEventListener(ev, () => { setTimeout(() => { zmPan = null }, 0); zmBody.classList.remove('panning') })
    document.getElementById('zm-x').addEventListener('click', () => zoom.close())
    zoom.addEventListener('click', (e) => { if (zmPan && zmPan.moved) return; if (e.target === zoom || e.target === zmBody) zoom.close() })
    zoom.addEventListener('close', () => document.body.classList.remove('zm-on'))
  }

  // ---- copy buttons ----------------------------------------------------------------------
  for (const b of document.querySelectorAll('button.copy')) b.addEventListener('click', async () => {
    const pre = b.parentElement.querySelector('pre')
    const txt = [...pre.childNodes].map((n) => (n.nodeType === 1 && n.classList.contains('c')) ? '' : n.textContent).join('')
      .split('\n').filter((x) => x.trim()).join('\n')
    try { await navigator.clipboard.writeText(txt) } catch (e) { return }
    const span = b.querySelector('[data-t]'); const was = span.innerHTML
    span.innerHTML = text('copied'); setTimeout(() => { span.innerHTML = was }, 1400)
  })

  // ---- version badge: read from the published source, never written into the page ---------
  const ver = document.getElementById('ver')
  if (ver && window.fetch) {
    fetch('https://raw.githubusercontent.com/jasoncheng7115/jt-glogarch/main/glogarch/__init__.py', { cache: 'no-cache' })
      .then((r) => r.ok ? r.text() : '')
      .then((s) => { const m = /__version__\s*=\s*["']([^"']+)["']/.exec(s || ''); if (m) { ver.textContent = 'v' + m[1]; ver.hidden = false } })
      .catch(() => { /* offline: no badge */ })
  }

  apply(pick())
})()
